, 31, '2.5'), (5746, 211, 126, 15, 12, 0, 50, 30, 4), (5747, 211, 127, 15, 12, 4, NULL, NULL, 'ผ.'), (5748, 211, 128, 15, 12, 4, NULL, NULL, 'ผ.'), (5749, 211, 193, 15, 14, 0, 43, 31, 3), (5750, 211, 194, 15, 14, 0, 48, 37, 4), (5751, 211, 195, 15, 14, 0, 45, 24, '2.5'), (5752, 211, 196, 15, 14, 0, 47, 36, 4), (5753, 211, 197, 15, 14, 0, 45, 25, 3), (5754, 211, 198, 15, 14, 0, 38, 30, '2.5'), (5755, 211, 199, 15, 14, 0, 43, 36, '3.5'), (5756, 211, 200, 15, 14, 0, 45, 28, 3), (5757, 211, 203, 15, 14, 0, 41, NULL, NULL), (5758, 211, 204, 15, 14, 0, 45, NULL, NULL), (5759, 211, 205, 15, 14, 0, NULL, NULL, NULL), (5760, 211, 206, 15, 14, 4, NULL, NULL, 'ผ.');
INSERT INTO `{prefix}_edocument` (`id`, `sender_id`, `receiver`, `last_update`, `document_no`, `detail`, `topic`, `ext`, `size`, `file`, `ip`, `urgency`) VALUES (1, 2, ',2,3,', 1778212998, '0001', 'แต่งตั้งครูประจำชั้นทุกระดับชั้น ให้ดูแลนักเรียน ติดตามการมาเรียน และประสานงานกับผู้ปกครองตลอดปีการศึกษา\n\n[ตัวอย่าง]', 'คำสั่งแต่งตั้งครูประจำชั้น ปีการศึกษา 2569', 'pdf', '48894', '1778212998.pdf', '192.168.1.237', 2), (2, 3, ',1,2,3,', 1778468805, '0002', 'กำหนดวันเปิด-ปิดภาคเรียน วันสอบกลางภาคและปลายภาค และกิจกรรมสำคัญของโรงเรียน ขอให้ทุกท่านใช้ประกอบการวางแผนการสอน\n\n[ตัวอย่าง]', 'ประกาศปฏิทินการศึกษา ปีการศึกษา 2569', 'pdf', '49917', '1778468805.pdf', '192.168.1.114', 2), (3, 2, ',1,2,3,', 1778558671, '0003', 'ขอเชิญคณะครูทุกท่านประชุมเตรียมความพร้อมก่อนเปิดภาคเรียน ณ ห้องประชุมใหญ่ เวลา 09.00 น.\n\n[ตัวอย่าง]', 'ขอเชิญประชุมครูก่อนเปิดภาคเรียนที่ 1/2569', 'pdf', '50412', '1778558671.pdf', '192.168.1.195', 1), (4, 3, ',2,', 1778745486, '0004', 'ส่งตารางสอนรายบุคคลและตารางเรียนของทุกห้อง ตรวจสอบความถูกต้องแล้วแจ้งฝ่ายวิชาการภายใน 3 วัน\n\n[ตัวอย่าง]', 'แจ้งตารางสอน ภาคเรียนที่ 1/2569', 'pdf', '47805', '1778745486.pdf', '192.168.1.32', 1), (5, 3, ',2,', 1779256630, '0005', 'ขอให้ครูผู้สอนทุกรายวิชาส่งแผนการจัดการเรียนรู้ภาคเรียนที่ 1 ที่ฝ่ายวิชาการภายในวันที่ 15 มิถุนายน\n\n[ตัวอย่าง]', 'ขอความร่วมมือส่งแผนการจัดการเรียนรู้', 'pdf', '48052', '1779256630.pdf', '192.168.1.180', 1), (6, 29, ',2,3,', 1779865537, '0006', 'ตารางเวรรักษาการณ์กลางวันและกลางคืนประจำเดือน ผู้ที่ติดภารกิจให้แลกเวรกันเองแล้วแจ้งงานธุรการล่วงหน้า\n\n[ตัวอย่าง]', 'แจ้งเวรรักษาการณ์ประจำเดือนมิถุนายน', 'jpg', '46674', '1779865537.jpg', '192.168.1.196', 2), (7, 11, ',3,', 1780388742, '0007', 'กลุ่มสาระการเรียนรู้ภาษาไทยขออนุมัติจัดกิจกรรมวันไหว้ครู ประจำปีการศึกษา 2569 ในวันพฤหัสบดีที่ 11 มิถุนายน\n\n[ตัวอย่าง]', 'ขออนุมัติจัดกิจกรรมวันไหว้ครู', 'pdf', '47119', '1780388742.pdf', '192.168.1.80', 2), (8, 2, ',1,2,3,', 1780628995, '0008', 'วาระการประชุม: รายงานผลการเปิดภาคเรียน การคัดกรองนักเรียน และการเตรียมการประชุมผู้ปกครอง\n\n[ตัวอย่าง]', 'ขอเชิญประชุมครูประจำเดือนมิถุนายน', 'pdf', '49528', '1780628995.pdf', '192.168.1.81', 1), (9, 4, ',2,', 1781056430, '0009', 'ขอให้ครูประจำชั้นคัดกรองนักเรียนตามระบบดูแลช่วยเหลือนักเรียน และส่งแบบสรุปที่งานแนะแนวภายในสิ้นเดือน\n\n[ตัวอย่าง]', 'ขอความร่วมมือคัดกรองนักเรียนกลุ่มเสี่ยง', 'pdf', '49055', '1781056430.pdf', '192.168.1.215', 1), (10, 4, ',2,3,', 1781505541, '0010', 'แบบฟอร์มแผนพัฒนาตนเองรายบุคคล ประจำปีงบประมาณ กรอกให้ครบถ้วนแล้วส่งที่งานบุคคล\n\n[ตัวอย่าง]', 'แบบฟอร์มแผนพัฒนาตนเองรายบุคคล (ID Plan)', 'jpg', '46224', '1781505541.jpg', '192.168.1.50', 2), (11, 3, ',2,', 1781845108, '0011', 'กำหนดประชุมผู้ปกครองนักเรียนทุกระดับชั้นวันเสาร์ที่ 27 มิถุนายน ขอให้ครูประจำชั้นเตรียมเอกสารและห้องประชุม\n\n[ตัวอย่าง]', 'แจ้งกำหนดการประชุมผู้ปกครองนักเรียน', 'pdf', '46823', '1781845108.pdf', '192.168.1.68', 2), (12, 29, ',2,3,', 1782459972, '0012', 'ตารางเวรรักษาการณ์กลางวันและกลางคืนประจำเดือน ผู้ที่ติดภารกิจให้แลกเวรกันเองแล้วแจ้งงานธุรการล่วงหน้า\n\n[ตัวอย่าง]', 'แจ้งเวรรักษาการณ์ประจำเดือนกรกฎาคม', 'jpg', '46613', '1782459972.jpg', '192.168.1.24', 2), (13, 2, ',1,2,3,', 1782881233, '0013', 'ให้ทุกห้องเรียนคัดกรองอาการนักเรียนทุกเช้า ทำความสะอาดห้องเรียน และแจ้งผู้ปกครองให้นักเรียนที่ป่วยพักรักษาตัวที่บ้าน\n\n[ตัวอย่าง]', 'มาตรการป้องกันโรคไข้หวัดใหญ่ในสถานศึกษา', 'pdf', '52674', '1782881233.pdf', '192.168.1.64', 0), (14, 2, ',1,2,3,', 1783051224, '0014', 'วาระการประชุม: การเตรียมสอบกลางภาค โครงการสัปดาห์วิทยาศาสตร์ และการเบิกจ่ายงบประมาณ\n\n[ตัวอย่าง]', 'ขอเชิญประชุมครูประจำเดือนกรกฎาคม', 'pdf', '49464', '1783051224.pdf', '192.168.1.172', 1), (15, 3, ',2,', 1783478189, '0015', 'แต่งตั้งกรรมการออกข้อสอบ กรรมการคุมสอบ และกรรมการตรวจข้อสอบกลางภาค ตามบัญชีรายชื่อแนบท้ายคำสั่ง\n\n[ตัวอย่าง]', 'คำสั่งแต่งตั้งคณะกรรมการดำเนินการสอบกลางภาค ภาคเรียนที่ 1/2569', 'pdf', '51055', '1783478189.pdf', '192.168.1.190', 1), (16, 29, ',2,', 1784104805, '0016', 'สำนักงานเขตพื้นที่การศึกษาเปิดรับสมัครครูเข้าร่วมอบรมการจัดการเรียนรู้เชิงรุก (Active Learning) ผู้สนใจสมัครได้ที่งานบุคคล\n\n[ตัวอย่าง]', 'สำนักงานเขตพื้นที่การศึกษาแจ้งโครงการอบรมพัฒนาครู', 'pdf', '49173', '1784104805.pdf', '192.168.1.233', 2), (17, 3, ',2,', 1784704833, '0017', 'ขอให้ครูที่ปรึกษาชุมนุมส่งชื่อชุมนุมและจำนวนนักเรียนที่รับ เพื่อเปิดให้นักเรียนลงทะเบียน\n\n[ตัวอย่าง]', 'ประกาศรับสมัครนักเรียนเข้าร่วมกิจกรรมชุมนุม', 'jpg', '44924', '1784704833.jpg', '192.168.1.248', 2), (18, 29, ',2,3,', 1785227456, '0018', 'ตารางเวรรักษาการณ์กลางวันและกลางคืนประจำเดือน ผู้ที่ติดภารกิจให้แลกเวรกันเองแล้วแจ้งงานธุรการล่วงหน้า\n\n[ตัวอย่าง]', 'แจ้งเวรรักษาการณ์ประจำเดือนสิงหาคม', 'jpg', '46581', '1785227456.jpg', '192.168.1.242', 2), (19, 29, ',1,2,3,', 1785738989, '0019', 'ขอเชิญคณะครูและบุคลากรร่วมกิจกรรมวันแม่แห่งชาติ วันที่ 11 สิงหาคม เวลา 08.00 น. ณ หอประชุมโรงเรียน\n\n[ตัวอย่าง]', 'ขอเชิญร่วมงานวันแม่แห่งชาติ', 'pdf', '46475', '1785738989.pdf', '192.168.1.178', 2), (20, 5, ',3,', 1786003047, '0020', 'กลุ่มสาระการเรียนรู้วิทยาศาสตร์และเทคโนโลยีขออนุมัติโครงการสัปดาห์วิทยาศาสตร์ วันที่ 17-21 สิงหาคม พร้อมงบประมาณ\n\n[ตัวอย่าง]', 'ขออนุมัติโครงการสัปดาห์วิทยาศาสตร์แห่งชาติ', 'pdf', '49875', '1786003047.pdf', '192.168.1.24', 2), (21, 2, ',1,2,3,', 1786080152, '0021', 'วาระการประชุม: สรุปผลการสอบกลางภาค นักเรียนที่มีผลการเรียนต่ำ และกิจกรรมสัปดาห์วิทยาศาสตร์\n\n[ตัวอย่าง]', 'ขอเชิญประชุมครูประจำเดือนสิงหาคม', 'pdf', '49463', '1786080152.pdf', '192.168.1.103', 1), (22, 4, ',2,3,', 1786682090, '0022', 'สรุประเบียบการลาป่วย ลากิจ และลาพักผ่อน พร้อมแบบฟอร์มใบลา ขอให้ยื่นใบลาล่วงหน้าตามระเบียบ\n\n[ตัวอย่าง]', 'แนวปฏิบัติการลาของข้าราชการครูและบุคลากรทางการศึกษา', 'pdf', '48634', '1786682090.pdf', '192.168.1.160', 2), (23, 8, ',3,', 1787190012, '0023', 'กลุ่มสาระการเรียนรู้คณิตศาสตร์รายงานผลการแข่งขันทักษะคณิตศาสตร์ระดับเขตพื้นที่ นักเรียนได้รับรางวัลเหรียญทอง 2 รายการ\n\n[ตัวอย่าง]', 'รายงานผลการแข่งขันทักษะทางวิชาการ', 'pdf', '49665', '1787190012.pdf', '192.168.1.60', 2), (24, 29, ',2,3,', 1787799422, '0024', 'ตารางเวรรักษาการณ์กลางวันและกลางคืนประจำเดือน ผู้ที่ติดภารกิจให้แลกเวรกันเองแล้วแจ้งงานธุรการล่วงหน้า\n\n[ตัวอย่าง]', 'แจ้งเวรรักษาการณ์ประจำเดือนกันยายน', 'jpg', '46489', '1787799422.jpg', '192.168.1.115', 2), (25, 14, ',2,', 1788238695, '0025', 'กลุ่มสาระการเรียนรู้สังคมศึกษาฯ กำหนดพานักเรียนชั้น ม.3 ทัศนศึกษาที่อุทยานประวัติศาสตร์ ขอครูร่วมเดินทาง 4 ท่าน\n\n[ตัวอย่าง]', 'กำหนดการทัศนศึกษานอกสถานที่ ระดับชั้น ม.3', 'pdf', '48154', '1788238695.pdf', '192.168.1.104', 2), (26, 2, ',1,2,3,', 1788496470, '0026', 'วาระการประชุม: การเตรียมสอบปลายภาค การส่งผลการเรียน และการประเมินผลการปฏิบัติงาน\n\n[ตัวอย่าง]', 'ขอเชิญประชุมครูประจำเดือนกันยายน', 'pdf', '49134', '1788496470.pdf', '192.168.1.100', 1), (27, 3, ',2,', 1788919393, '0027', 'แต่งตั้งกรรมการดำเนินการสอบปลายภาค ตามบัญชีรายชื่อแนบท้ายคำสั่ง ขอให้ปฏิบัติหน้าที่อย่างเคร่งครัด\n\n[ตัวอย่าง]', 'คำสั่งแต่งตั้งคณะกรรมการดำเนินการสอบปลายภาค ภาคเรียนที่ 1/2569', 'pdf', '50283', '1788919393.pdf', '192.168.1.154', 1), (28, 4, ',2,', 1789447630, '0028', 'ขอให้กลุ่มสาระการเรียนรู้สำรวจความต้องการวัสดุและครุภัณฑ์ แล้วส่งแบบสำรวจที่งานพัสดุภายในสิ้นเดือน\n\n[ตัวอย่าง]', 'แบบสำรวจความต้องการวัสดุการเรียนการสอน ภาคเรียนที่ 2/2569', 'jpg', '47967', '1789447630.jpg', '192.168.1.48', 2), (29, 3, ',2,', 1789720743, '0029', 'ขอให้ครูผู้สอนบันทึกคะแนนและผลการเรียนในระบบให้ครบถ้วนภายในวันที่ 10 ตุลาคม\n\n[ตัวอย่าง]', 'แจ้งกำหนดส่งผลการเรียน ภาคเรียนที่ 1/2569', 'pdf', '47437', '1789720743.pdf', '192.168.1.79', 0), (30, 2, ',1,2,3,', 1790239760, '0030', 'สรุปผลการประเมินคุณภาพภายในตามมาตรฐานการศึกษาของสถานศึกษา พร้อมข้อเสนอแนะเพื่อการพัฒนา\n\n[ตัวอย่าง]', 'สรุปผลการประเมินคุณภาพภายในสถานศึกษา', 'pdf', '48921', '1790239760.pdf', '192.168.1.182', 2), (31, 29, ',3,', 1790313625, '0031', 'รายงานการเบิกจ่ายงบประมาณตามโครงการ ประจำไตรมาสที่ 4 ของปีงบประมาณ\n\n[ตัวอย่าง]', 'รายงานการใช้จ่ายงบประมาณไตรมาสที่ 4', 'pdf', '45269', '1790313625.pdf', '192.168.1.75', 2), (32, 29, ',2,3,', 1790557597, '0032', 'ตารางเวรรักษาการณ์กลางวันและกลางคืนประจำเดือน ผู้ที่ติดภารกิจให้แลกเวรกันเองแล้วแจ้งงานธุรการล่วงหน้า\n\n[ตัวอย่าง]', 'แจ้งเวรรักษาการณ์ประจำเดือนตุลาคม', 'jpg', '46341', '1790557597.jpg', '192.168.1.54', 2), (33, 29, ',1,2,3,', 1790732932, '0033', 'ประกาศรายชื่อนักเรียนที่ได้รับทุนการศึกษาประจำปี ขอให้ครูประจำชั้นแจ้งนักเรียนและผู้ปกครอง\n\n[ตัวอย่าง]', 'ประกาศรายชื่อนักเรียนที่ได้รับทุนการศึกษา', 'pdf', '47214', '1790732932.pdf', '192.168.1.156', 2), (34, 2, ',1,2,3,', 1790842846, '0034', 'โรงเรียนเปิดใช้ระบบสารสนเทศสำหรับบันทึกผลการเรียนและรับหนังสือราชการ ชื่อผู้ใช้คือเลขประจำตัวประชาชน รหัสผ่านคือวันเกิด\n\n[ตัวอย่าง]', 'แจ้งการใช้งานระบบสารสนเทศโรงเรียน', 'pdf', '51759', '1790842846.pdf', '192.168.1.243', 1), (35, 2, ',1,2,3,', 1790913600, '0035', 'วาระการประชุม: สรุปผลการเรียนภาคเรียนที่ 1 การปิดภาคเรียน และการเตรียมการภาคเรียนที่ 2\n\n[ตัวอย่าง]', 'ขอเชิญประชุมครูประจำเดือนตุลาคม', 'pdf', '49424', '1790913600.pdf', '192.168.1.177', 0);
